1	import React from "react";
2	import { call, on } from "../../api.js";
3	import "./game.css";
4	
5	const LABEL = {
6	  stopped: "Stopped",
7	  starting: "Starting",
8	  running: "Running",
9	  error: "Error",
10	  offline: "Offline",
11	  connecting: "Joining",
12	  online: "In game",
13	};
14	
15	// One-line summary of a bot tool call for the overlay.
16	function describe(a) {
