content.content:
1	#!/usr/bin/env node
2	// Benana minecraft MCP server (stdio, newline-delimited JSON-RPC). Owner: Track A.
3	// Gives a Claude Code playtester control of the in-game bot through Benana's local control API,
4	// and records the verdict file the studio pipeline reads (docs/hackathon/CONTRACTS.md).
5	// Env: BENANA_GAME_URL, BENANA_VERDICT_FILE, BENANA_TEST_PLAN, BENANA_RUN_ID.
6	const fs = require('node:fs');
7	const path = require('node:path');
8	const readline = require('node:readline');
9	
10	const gameUrl = process.env.BENANA_GAME_URL;
11	const verdictFile = process.env.BENANA_VERDICT_FILE;
12	const testPlanFile = process.env.BENANA_TEST_PLAN;
13	const runId = process.env.BENANA_RUN_ID || 'manual';
14	const startedAt = Date.now();
15	
16	const obj = (properties, required = []) => ({ type: 'object', properties, required });
17	const entityId = { type: 'number', description: 'Entity id from nearby_entities' };
18	const position = { type: 'array', items: { type: 'number' }, minItems: 3, maxItems: 3, description: '[x, y, z]' };
19	const trackTicks = { type: 'number', description: 'Record the target for this many ticks right after the action (20 ticks = 1s). Use it whenever the expected effect is movement.' };
20	
21	const tools = [
22	  { name: 'game_setup', description: 'Run server console commands as the bot (no leading slash). `@bot` is the bot; ^ and ~ coordinates are relative to it. Use for the test plan setup: give items, summon mobs, set time.', inputSchema: obj({ commands: { type: 'array', items: { type: 'string' } } }, ['commands']) },
23	  { name: 'reset_arena', description: 'Rebuild the flat arena, remove all mobs, items and projectiles, and put the bot back at the center with an empty inventory. Use it between checks when an earlier check left mobs, craters or a cooldown state behind; then rerun your setup.', inputSchema: obj({}) },
24	  { name: 'bot_state', description: 'Bot position, health, held item and inventory.', inputSchema: obj({}) },
25	  { name: 'nearby_entities', description: 'Entities near the bot with id, type, position, velocity, distance and health (living entities), nearest first.', inputSchema: obj({ radius: { type: 'number' } }) },
26	  { name: 'equip', description: 'Hold an inventory item, e.g. golden_sword.', inputSchema: obj({ item: { type: 'string' } }, ['item']) },
27	  { name: 'look_at', description: 'Aim at an entity or position.', inputSchema: obj({ entityId, position }) },
28	  { name: 'move_to', description: 'Walk to an entity or position.', inputSchema: obj({ entityId, position, range: { type: 'number' } }) },
29	  { name: 'attack', description: 'Left-click (hit) an entity with the held item. Walks into reach first if needed.', inputSchema: obj({ entityId, trackTicks }, ['entityId']) },
30	  { name: 'attack_sequence', description: 'Hit several entities back to back, intervalTicks apart (default 4), in ONE call, and track each. Use for cooldowns and combos; separate attack calls are seconds apart.', inputSchema: obj({ entityIds: { type: 'array', items: { type: 'number' } }, intervalTicks: { type: 'number' }, trackTicks }, ['entityIds']) },
31	  { name: 'use_item', description: 'Right-click with the held item, on an entity if entityId is given (holdTicks = how long to hold right-click, default 5). For bows, crossbows, tridents and throwables use `shoot` instead.', inputSchema: obj({ entityId, trackTicks, holdTicks: { type: 'number' } }) },
32	  {
