1	// Mod Studio pipeline: prompt -> spec/test plan -> build -> deploy -> playtest -> fix -> retry.
2	// Interface with the game runtime: docs/hackathon/CONTRACTS.md.
3	const fs = require('node:fs');
4	const path = require('node:path');
5	const { appRoot, dataDir } = require('../env.cjs');
6	const game = require('../game/index.cjs');
7	const neatlogs = require('../neatlogs.cjs');
8	const repo = require('./repo.cjs');
9	const prompts = require('./prompts.cjs');
10	const { runClaude, MODELS } = require('./claude.cjs');
11	
12	const MAX_ATTEMPTS = 3;
13	const studioDir = path.join(dataDir, 'studio');
14	const lessonsFile = path.join(studioDir, 'lessons.json');
15	const SEEDED = path.join(appRoot, 'fixtures', 'seeded');
16	
17	const mods = new Map();
18	let active = null; // { modId, stop }
19	let emit = () => {};
20	let log = () => {};
21	
22	const now = () => Date.now();
23	const modFile = (id) => path.join(studioDir, id, 'mod.json');
24	
25	// The newest jar this mod built (Maven overwrites target/<Name>.jar on every attempt).
26	function jarOf(mod) {
27	  const built = [...mod.attempts].reverse().find((a) => a.build?.ok && a.build.jar && fs.existsSync(a.build.jar));
28	  if (built) return built.build.jar;
29	  const fallback = mod.repoDir && path.join(mod.repoDir, 'target', `${mod.name}.jar`);
30	  return fallback && fs.existsSync(fallback) ? fallback : null;
31	}
32	
33	function publicMod(mod) {
34	  const { feed, ...rest } = mod;
35	  return { ...rest, feedCount: feed.length, running: active?.modId === mod.id, loadable: Boolean(jarOf(mod)) };
36	}
37	
38	let saveTimers = new Map();
39	function save(mod) {
40	  mod.updatedAt = now();
41	  emit('studio:mod', publicMod(mod));
42	  clearTimeout(saveTimers.get(mod.id));
43	  saveTimers.set(mod.id, setTimeout(() => {
44	    fs.mkdirSync(path.dirname(modFile(mod.id)), { recursive: true });
45	    fs.writeFileSync(modFile(mod.id), JSON.stringify(mod, null, 2));
46	  }, 300));
47	}
48	
49	function load() {
50	  if (!fs.existsSync(studioDir)) return;
51	  for (const id of fs.readdirSync(studioDir)) {
52	    try {
53	      const mod = JSON.parse(fs.readFileSync(modFile(id), 'utf8'));
54	      if (!['passed', 'failed', 'stopped'].includes(mod.status)) mod.status = 'stopped';
55	      mods.set(mod.id, mod);
56	    } catch {}
57	  }
58	}
59	
60	function feed(mod, entry) {
61	  const item = { at: now(), ...entry };
62	  mod.feed.push(item);
63	  if (mod.feed.length > 1500) mod.feed.splice(0, 300);
64	  emit('studio:feed', { modId: mod.id, item });
65	}
66	
67	function setPhase(mod, phase, text) {
68	  mod.phase = phase;
69	  if (text) feed(mod, { role: 'benana', kind: 'phase', phase, text });
70	  save(mod);
71	}
72	
73	function lessons() {
74	  try { return JSON.parse(fs.readFileSync(lessonsFile, 'utf8')); } catch { return []; }
75	}
76	
77	function addLesson(lesson, mod) {
78	  const all = lessons();
79	  all.push({ lesson, mod: mod.name, at: now() });
80	  fs.mkdirSync(studioDir, { recursive: true });
81	  fs.writeFileSync(lessonsFile, JSON.stringify(all.slice(-20), null, 2));
82	}
83	
84	function parseJson(text) {
85	  const fenced = String(text).match(/```(?:json)?\s*([\s\S]*?)```/);
86	  const raw = fenced ? fenced[1] : String(text).slice(String(text).indexOf('{'), String(text).lastIndexOf('}') + 1);
87	  return JSON.parse(raw);
88	}
89	
90	const slugify = (s) => s.replace(/([a-z])([A-Z])/g, '$1-$2').replace(/[^a-zA-Z0-9]+/g, '-').replace(/^-|-$/g, '').toLowerCase().slice(0, 32);
91	
92	// Runs one agent session for a mod and records it on the attempt.
93	async function agent(mod, attempt, role, options) {
94	  const session = { role, model: options.model, startedAt: now(), sessionId: null };
95	  if (attempt) attempt.sessions.push(session);
96	  else mod.sessions.push(session);
97	  save(mod);
98	  const handle = runClaude({
99	    ...options,
100	    onEvent: (ev) => {
101	      if (ev.kind === 'session') { session.sessionId = ev.sessionId; save(mod); return; }
102	      feed(mod, { attempt: attempt?.n ?? 0, role, ...ev, input: undefined });
103	      if (role === 'playtester' && ev.kind === 'tool') emit('studio:playtester', { modId: mod.id, tool: ev.name, input: ev.input });
104	    },
105	  });
106	  active.stop = handle.stop;
107	  const result = await handle.done;
108	  Object.assign(session, { endedAt: now(), ok: result.ok, error: result.error, usage: result.usage, sessionId: result.sessionId || session.sessionId });
109	  save(mod);
110	  if (active?.stopped) throw new Error('Stopped by user.');
111	  return result;
112	}
113	
114	async function specPhase(mod) {
115	  if (mod.seed) {
116	    const seeded = JSON.parse(fs.readFileSync(path.join(SEEDED, 'spec.json'), 'utf8'));
117	    feed(mod, { role: 'benana', kind: 'note', text: 'Seeded bug fallback: using the labeled LaunchSword fixture spec instead of the spec agent.' });
118	    return seeded;
119	  }
120	  const work = path.join(studioDir, mod.id, 'spec');
121	  fs.mkdirSync(work, { recursive: true });
122	  const res = await agent(mod, null, 'spec', { cwd: work, prompt: prompts.spec(mod.prompt), model: MODELS.build, tools: [] });
123	  if (!res.ok) throw new Error(`Spec agent failed: ${res.error}`);
124	  const spec = parseJson(res.final);
125	  if (!/^[A-Za-z]{2,24}$/.test(spec.modName || '')) spec.modName = 'StudioMod';
126	  if (!spec.testPlan?.checks?.length) throw new Error('Spec agent returned no test checks.');
127	  spec.testPlan.modName = spec.modName;
128	  return spec;
129	}
130	
131	async function trace(sessionId) {
132	  if (!sessionId || !neatlogs.configured()) return '';
