236	      ? { kind: 'playtest', summary: failed.length ? failed.map((c) => `${c.id}: ${c.observed}`).join(' · ') : `${attempt.verdict.serverErrors.length} server error(s)` }
237	      : { kind: 'playtest', summary: attempt.verdict.error || 'The playtester did not finish.' };
