267	    for (let n = 1; n <= MAX_ATTEMPTS; n++) {
268	      const attempt = await runAttempt(mod, n, previous);
269	      attempt.status = attempt.failure ? 'failed' : 'passed';
270	      attempt.endedAt = now();
