295	function create({ prompt, seed = false }) {
296	  if (active) throw new Error('Another mod is running. Stop it or wait for it to finish.');
297	  if (game.status().deploying) throw new Error('A mod is being loaded into the game. Try again in a few seconds.');
298	  const text = String(prompt || '').trim();
299	  if (!seed && text.length < 8) throw new Error('Describe the mod in a sentence.');
300	  const id = `mod_${now().toString(36)}`;
301	  const mod = {
302	    id, prompt: seed ? text || 'A golden sword that launches any mob it hits into the sky with particles, with a 3 second cooldown.' : text,
303	    seed: Boolean(seed), name: 'New mod', status: 'queued', phase: 'queued', createdAt: now(), updatedAt: now(),
304	    spec: null, testPlan: null, repoDir: null, partners: null, sessions: [], attempts: [], feed: [], error: null,
305	  };
306	  mods.set(id, mod);
307	  save(mod);
308	  run(mod);
309	  return publicMod(mod);
