324	    'studio:get': ({ id }) => {
325	      const mod = mods.get(id);
326	      if (!mod) throw new Error('Unknown mod.');
327	      return { ...publicMod(mod), feed: mod.feed };
328	    },
329	    'studio:create': create,
330	    // Puts a mod's latest build on the server so the user can play it or watch it in the live view.
331	    'studio:load': async ({ id }) => {
332	      if (active) throw new Error('A mod is building. Switch mods after it finishes.');
333	      const mod = mods.get(id);
334	      if (!mod) throw new Error('Unknown mod.');
335	      const jar = jarOf(mod);
336	      if (!jar) throw new Error(`${mod.name} has no built jar yet.`);
337	      const out = await game.deployPlugin({ jarPath: jar, emit });
338	      if (!out.loaded) throw new Error(`${mod.name} did not load: ${out.errors[0] || 'see the server log'}`);
339	      return out;
340	    },
341	    'studio:stop': ({ id }) => {
342	      if (active?.modId !== id) return false;
343	      active.stopped = true;
344	      active.stop();
345	      return true;
346	    },
347	    'studio:evidence': ({ sessionId }) => neatlogs.evidence({ sessionId }),
348	    'studio:checkpoints': async ({ id }) => {
349	      const mod = mods.get(id);
350	      return mod?.repoDir ? repo.checkpoints(mod.repoDir) : { ok: false, items: [], error: 'No repository yet.' };
351	    },
