353	    'studio:file': ({ id, path: rel }) => repo.readFile(repoOf(id), rel),
354	    'studio:diff': ({ id, sha }) => repo.diff(repoOf(id), sha),
355	    'studio:lessons': () => lessons(),
356	    'studio:partners': async () => ({ neatlogs: await neatlogs.status() }),
357	  };
358	}
359	
360	const busy = () => Boolean(active);
361	
362	module.exports = { handlers, busy };
