2	const fs = require('node:fs');
3	const net = require('node:net');
4	const path = require('node:path');
5	const crypto = require('node:crypto');
6	const { dataDir } = require('../env.cjs');
7	const { spawnExecutable, terminateProcessTree } = require('../processes.cjs');
8	
9	const VERSION = '1.21.4';
10	const UA = 'benana/0.1 (neatHack)';
11	const dir = path.join(dataDir, 'game', 'server');
12	const PORT = Number(process.env.BENANA_MC_PORT) || 25599;
13	const RCON_PORT = Number(process.env.BENANA_RCON_PORT) || 25598;
