18	async function ensureJar(log) {
19	  fs.mkdirSync(dir, { recursive: true });
20	  const meta = await fetch(`https://fill.papermc.io/v3/projects/paper/versions/${VERSION}/builds/latest`, { headers: { 'User-Agent': UA } });
21	  if (!meta.ok) throw new Error(`Paper build lookup failed: ${meta.status}`);
22	  const dl = (await meta.json()).downloads?.['server:default'];
23	  if (!dl?.url) throw new Error('Paper build lookup returned no server download.');
24	  const jar = path.join(dir, dl.name);
25	  if (fs.existsSync(jar)) return jar;
26	  log(`downloading ${dl.name} (${Math.round(dl.size / 1e6)} MB)…`);
27	  const res = await fetch(dl.url, { headers: { 'User-Agent': UA } });
28	  if (!res.ok) throw new Error(`Paper download failed: ${res.status}`);
29	  const buf = Buffer.from(await res.arrayBuffer());
30	  const sha = crypto.createHash('sha256').update(buf).digest('hex');
31	  if (sha !== dl.checksums.sha256) throw new Error('Paper download checksum mismatch.');
32	  fs.writeFileSync(jar, buf);
33	  return jar;
34	}
