36	function localJar() {
37	  if (!fs.existsSync(dir)) return null;
38	  const jar = fs.readdirSync(dir).filter((f) => /^paper-.*\.jar$/.test(f)).sort().pop();
39	  return jar ? path.join(dir, jar) : null;
