  cursor: pointer;
}
/* Beats the studio's `button { color: inherit }`, which left dark-on-light buttons with light text. */
.game-pane .game-btn {
  color: #0c0d0f;
}
.game-pane .game-btn.ghost {
  color: var(--text, #ececee);
}
.game-btn.ghost {
  border-color: var(--line-strong, rgba(255, 255, 255, 0.14));
  background: transparent;
  color: var(--text, #ececee);
  font-weight: 500;
}
.game-btn.ghost:hover {
  background: var(--hover, #1c1e22);
}
.game-btn:disabled {
  opacity: 0.5;
  cursor: default;
}
.game-view {
  position: relative;
  flex: 1;
  min-height: 0;
  background: #08090a;
}
.game-view iframe {
  display: block;
  width: 100%;
  height: 100%;
  border: 0;
}
.game-empty {
  display: grid;
  place-items: center;
  height: 100%;
  padding: 24px;
  color: var(--text-3, #6c707a);
  font-size: 13px;
  text-align: center;
  background:
    linear-gradient(rgba(255, 255, 255, 0.025) 1px, transparent 1px) 0 0 / 24px 24px,
    linear-gradient(90deg, rgba(255, 255, 255, 0.025) 1px, transparent 1px) 0 0 / 24px 24px;
}
.game-actions {
  position: absolute;
  left: 12px;
  bottom: 12px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  max-width: calc(100% - 24px);
}
.game-action {
  display: flex;
  align-items: baseline;
  gap: 8px;
  padding: 5px 9px;
  border-radius: 6px;
  background: rgba(8, 9, 10, 0.78);
  backdrop-filter: blur(6px);
  color: #ececee;
  font-size: 11.5px;
}
.game-action span {
  color: var(--good, #4cc38a);
  font-weight: 600;
}
.game-action.error span {
  color: var(--bad, #e5484d);
}
.game-action code {
  overflow: hidden;
  font-family: var(--mono, Consolas, monospace);
  font-size: 11px;
  color: #c9ccd2;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.game-error {
  padding: 8px 14px;
  border-top: 1px solid rgba(229, 72, 77, 0.3);
  background: rgba(229, 72, 77, 0.08);
  color: #ff9a9d;
  font-size: 12px;
}
.game-log {
  max-height: 140px;
  margin: 0;
  padding: 10px 14px;
  overflow: auto;
  border-top: 1px solid var(--line, rgba(255, 255, 255, 0.08));
  font-family: var(--mono, Consolas, monospace);
  font-size: 11px;
  color: var(--text-2, #a0a3ab);
  white-space: pre-wrap;
}

