.game-pane {
  display: flex;
  flex-direction: column;
  min-height: 0;
  border: 1px solid var(--line, rgba(255, 255, 255, 0.08));
  border-radius: 10px;
  background: var(--panel, #121316);
  overflow: hidden;
}
.game-bar {
  display: flex;
  align-items: center;
  gap: 10px;
  height: 44px;
  padding: 0 8px 0 14px;
  border-bottom: 1px solid var(--line, rgba(255, 255, 255, 0.08));
  font-size: 12px;
  color: var(--text-2, #a0a3ab);
  white-space: nowrap;
}
.game-bar strong {
  color: var(--text, #ececee);
  font-size: 13px;
  font-weight: 600;
}
.game-meta {
  color: var(--text-3, #6c707a);
}
.game-state {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.game-spacer {
  flex: 1;
}
.game-mod {
  flex: none;
  overflow: hidden;
  max-width: 180px;
  padding: 1px 8px;
  border: 1px solid var(--line-strong, rgba(255, 255, 255, 0.14));
  border-radius: 99px;
  color: var(--text-2, #a0a3ab);
  font-size: 11px;
  text-overflow: ellipsis;
}
.game-mod.match {
  border-color: rgba(76, 195, 138, 0.35);
  color: var(--good, #4cc38a);
}
.game-bar button {
  flex: none;
}
@media (max-width: 1680px) {
  .game-meta {
    display: none;
  }
}
.game-btn.load {
  overflow: hidden;
  max-width: 190px;
  text-overflow: ellipsis;
}
.game-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--text-3, #6c707a);
}
.game-dot.starting,
.game-dot.connecting {
  background: var(--warn, #f0b429);
}
.game-dot.running,
.game-dot.online {
  background: var(--good, #4cc38a);
  box-shadow: 0 0 0 3px rgba(76, 195, 138, 0.16);
}
.game-dot.error {
  background: var(--bad, #e5484d);
}
.game-tag {
  padding: 1px 7px;
  border: 1px solid var(--line-strong, rgba(255, 255, 255, 0.14));
  border-radius: 99px;
  color: var(--text-2, #a0a3ab);
  font-size: 11px;
}
.game-btn {
  height: 28px;
  padding: 0 12px;
  border: 1px solid transparent;
  border-radius: 6px;
  background: var(--text, #ececee);
  color: #0c0d0f;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
}
/* Beats the studio's `button { color: inherit }`, which left dark-on-light buttons with light text. */
.game-pane .game-btn {
  color: #0c0d0f;
}
.game-pane .game-btn.ghost {
  color: var(--text, #ececee);
}
.game-btn.ghost {
  border-color: var(--line-strong, rgba(255, 255, 255, 0.14));
  background: transparent;
  color: var(--text, #ececee);
  font-weight: 500;
}
.game-btn.ghost:hover {
  background: var(--hover, #1c1e22);
}
.game-btn:disabled {
  opacity: 0.5;
  cursor: default;
}
.game-view {
  position: relative;
  flex: 1;
  min-height: 0;
  background: #08090a;
}
.game-view iframe {
  display: block;
  width: 100%;
  height: 100%;
  border: 0;
}
.game-empty {
  display: grid;
  place-items: center;
  height: 100%;
  padding: 24px;
  color: var(--text-3, #6c707a);
  font-size: 13px;
  text-align: center;
  background:
    linear-gradient(rgba(255, 255, 255, 0.025) 1px, transparent 1px) 0 0 / 24px 24px,
    linear-gradient(90deg, rgba(255, 255, 255, 0.025) 1px, transparent 1px) 0 0 / 24px 24px;
}
.game-actions {
  position: absolute;
  left: 12px;
  bottom: 12px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  max-width: calc(100% - 24px);
}
.game-action {
  display: flex;
  align-items: baseline;
  gap: 8px;
  padding: 5px 9px;
  border-radius: 6px;
  background: rgba(8, 9, 10, 0.78);
  backdrop-filter: blur(6px);
  color: #ececee;
  font-size: 11.5px;
}
.game-action span {
  color: var(--good, #4cc38a);
  font-weight: 600;
}
.game-action.error span {
  color: var(--bad, #e5484d);
}
.game-action code {
  overflow: hidden;
  font-family: var(--mono, Consolas, monospace);
  font-size: 11px;
  color: #c9ccd2;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.game-error {
  padding: 8px 14px;
  border-top: 1px solid rgba(229, 72, 77, 0.3);
  background: rgba(229, 72, 77, 0.08);
  color: #ff9a9d;
  font-size: 12px;
}
.game-log {
  max-height: 140px;
  margin: 0;
  padding: 10px 14px;
  overflow: auto;
  border-top: 1px solid var(--line, rgba(255, 255, 255, 0.08));
  font-family: var(--mono, Consolas, monospace);
  font-size: 11px;
  color: var(--text-2, #a0a3ab);
  white-space: pre-wrap;
}

